'use strict'
// Reads the facts of ONE client's deployment out of its rendered Worker config
// (cloudflare/wrangler.toml, generated by render-wrangler.mjs), so the release
// kit and the ops scripts never carry a client's account, database, bucket,
// Worker or site as a constant. Pure: it parses text it is handed.
//
// The parser is line based on purpose. It reads files this repository's own
// renderer wrote from cloudflare/wrangler.template.toml, where every key is a
// plain `key = "value"` on one line, and there is no TOML parser in this
// package's dependencies.

class TargetError extends Error {
  constructor(code, message) {
    super(message || code)
    this.name = 'TargetError'
    this.code = code
  }
}

const DB_BINDING = 'DB'
const IMPORT_DB_BINDING = 'IMPORT_DB'
const ACCOUNT_ID = /^[0-9a-f]{32}$/
const DATABASE_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/

function stripComments(text) {
  return String(text).replace(/\r\n?/g, '\n').split('\n').filter((line) => !/^\s*#/.test(line)).join('\n')
}

// Splits the body into the root keys and its [table] / [[array]] blocks.
function blocks(body) {
  const out = []
  let current = { header: '', lines: [] }
  out.push(current)
  for (const line of body.split('\n')) {
    const h = /^\s*(\[\[?[A-Za-z0-9_.-]+\]\]?)\s*$/.exec(line)
    if (h) { current = { header: h[1], lines: [] }; out.push(current); continue }
    current.lines.push(line)
  }
  return out
}

function value(lines, key) {
  const re = new RegExp(`^\\s*${key}\\s*=\\s*"([^"]*)"\\s*$`)
  for (const line of lines) {
    const m = re.exec(line)
    if (m) return m[1]
  }
  return undefined
}

function bareValue(lines, key) {
  const re = new RegExp(`^\\s*${key}\\s*=\\s*([^\\s#]+)\\s*$`)
  for (const line of lines) {
    const m = re.exec(line)
    if (m) return m[1]
  }
  return undefined
}

// config text -> { accountId, workerName, ... }. Throws TargetError('no-config')
// when the text has no account or no main database, which is what a missing or
// half-rendered file looks like.
function parseTarget(text) {
  const body = stripComments(text)
  const parts = blocks(body)
  const root = parts[0].lines
  const accountId = value(root, 'account_id')
  const workerName = value(root, 'name')
  const databases = parts.filter((b) => b.header === '[[d1_databases]]').map((b) => ({
    binding: value(b.lines, 'binding'),
    name: value(b.lines, 'database_name'),
    id: value(b.lines, 'database_id'),
    migrationsDir: value(b.lines, 'migrations_dir'),
    migrationsTable: value(b.lines, 'migrations_table'),
  }))
  const main = databases.find((d) => d.binding === DB_BINDING)
  const importDb = databases.find((d) => d.binding === IMPORT_DB_BINDING)
  if (!accountId || !workerName || !main || !main.name || !main.id) {
    throw new TargetError('no-config', 'The Worker config has no account, Worker name or main database')
  }
  const vars = parts.find((b) => b.header === '[vars]')
  const assets = parts.filter((b) => b.header === '[[r2_buckets]]').find((b) => value(b.lines, 'binding') === 'ASSETS')
  const dataset = parts.find((b) => b.header === '[[analytics_engine_datasets]]')
  const queues = {}
  for (const b of parts.filter((x) => x.header === '[[queues.producers]]')) queues[value(b.lines, 'binding')] = value(b.lines, 'queue')
  const consumers = parts.filter((x) => x.header === '[[queues.consumers]]').map((b) => value(b.lines, 'queue'))
  const routeBlock = /^routes\s*=\s*\[([\s\S]*?)^\]/m.exec(parts[0].lines.join('\n'))
  const routes = routeBlock ? [...routeBlock[1].matchAll(/pattern\s*=\s*"([^"]+)"/g)].map((m) => m[1]) : []
  return {
    accountId,
    workerName,
    workersDev: bareValue(root, 'workers_dev') === 'true',
    routes,
    databases,
    main,
    importDb: importDb || null,
    assetsBucket: assets ? value(assets.lines, 'bucket_name') : undefined,
    analyticsDataset: dataset ? value(dataset.lines, 'dataset') : undefined,
    queues,
    consumers,
    vars: vars ? Object.fromEntries(vars.lines.map((l) => /^([A-Z][A-Z0-9_]*)\s*=\s*"([^"]*)"\s*$/.exec(l)).filter(Boolean).map((m) => [m[1], m[2]])) : {},
  }
}

// What the environment says this deployment must be (the GitHub variables
// CF_ACCOUNT_ID, D1_MAIN_ID and ADMIN_URL, or the same names exported by hand;
// PLAN_TIER is the plan a release must be for, checked where the plan is chosen).
function expectationsFromEnv(env = process.env) {
  const pick = (name) => {
    const v = env[name]
    return typeof v === 'string' && v.trim() ? v.trim() : ''
  }
  return { accountId: pick('CF_ACCOUNT_ID'), d1MainId: pick('D1_MAIN_ID'), adminUrl: pick('ADMIN_URL').replace(/\/+$/, ''), planTier: pick('PLAN_TIER') }
}

// Compares a parsed target with the expectations. Returns problems as fixed
// phrases (never values), so the result can go to a public log.
function checkExpectations(target, expect, { accountSecret = '', require: need = false } = {}) {
  const problems = []
  const e = expect || {}
  if (need && !(e.accountId && e.d1MainId && e.adminUrl)) {
    problems.push('the expected account, main database id and admin url are not all provided (CF_ACCOUNT_ID, D1_MAIN_ID, ADMIN_URL)')
  }
  if (!ACCOUNT_ID.test(target.accountId)) problems.push('the rendered account id is not 32 hex characters')
  if (!DATABASE_ID.test(target.main.id)) problems.push('the rendered main database id is not a UUID')
  if (e.accountId && e.accountId !== target.accountId) problems.push('the rendered account id differs from the expected one (CF_ACCOUNT_ID)')
  if (e.d1MainId && e.d1MainId !== target.main.id) problems.push('the rendered main database id differs from the expected one (D1_MAIN_ID)')
  if (e.adminUrl && String(e.adminUrl).replace(/\/+$/, '') !== String(target.vars.BUSINESS_OS_ADMIN_URL || '').replace(/\/+$/, '')) {
    problems.push('the rendered admin url differs from the expected one (ADMIN_URL)')
  }
  if (accountSecret && accountSecret !== target.accountId) problems.push('the account of the CLOUDFLARE_ACCOUNT_ID secret differs from the rendered account')
  return problems
}

// `wrangler whoami --json` -> true when the token can act in this account.
function whoamiHasAccount(output, accountId) {
  const text = String(output || '')
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] !== '{') continue
    try {
      const json = JSON.parse(text.slice(i))
      return !!json && json.loggedIn !== false && Array.isArray(json.accounts) && json.accounts.some((a) => a && a.id === accountId)
    } catch { /* keep scanning */ }
  }
  return false
}

module.exports = {
  TargetError, DB_BINDING, IMPORT_DB_BINDING, ACCOUNT_ID, DATABASE_ID,
  parseTarget, expectationsFromEnv, checkExpectations, whoamiHasAccount,
}
